/** La ficha del laboratorio, o null si ese slug no tiene ninguna. */
export async function cargarFicha(slug: string): Promise<FichaTeoricaData | null> {
  const cargar = FICHAS[slug];
  if (!cargar) return null;
  try {
    return await cargar();
  } catch {
    // Una ficha rota no puede dejar al alumno sin laboratorio.
    return null;
  }
}
